<template>
 <section class="ph-app" :class="{'ph-app--standalone':standalone}" @dragover.prevent @drop.prevent="drop">
  <div class="ph-topbar">
   <div class="ph-brand"><PhotosIcon name="logo"/><span>Photos</span></div>
   <form class="ph-search" role="search" @submit.prevent="refresh"><PhotosIcon name="search"/><input v-model="query" aria-label="Search photos and videos" placeholder="Search photos and videos" maxlength="200"/><button v-if="query" type="button" aria-label="Clear search" @click="query='';refresh()"><PhotosIcon name="close"/></button></form>
   <button class="ph-icon-button" aria-label="Refresh photos" title="Refresh photos" :disabled="busy" @click="refresh"><PhotosIcon name="refresh"/></button>
   <button class="ph-avatar" :title="user?.username||'Account'" @click="accountOpen=!accountOpen">{{(user?.username||'?').slice(0,1).toUpperCase()}}</button>
  </div>
  <div v-if="accountOpen" class="ph-account"><strong>{{user?.username}}</strong><a :href="api.filebrowserURL||'../'" target="_blank" rel="noopener">Open FileBrowser</a><button @click="accountOpen=false">Close</button></div>
  <div class="ph-body">
   <nav class="ph-navigation" aria-label="Photos navigation">
    <button v-for="tab in tabs" :key="tab.id" :class="{'ph-active':mode===tab.id}" @click="mode=tab.id;refresh()"><PhotosIcon :name="tab.icon"/><span>{{tab.label}}</span></button>
    <div class="ph-library-choice"><label for="ph-source">Your library</label><select id="ph-source" v-model="source" @change="folder='/';refresh()"><option v-for="name in sources" :key="name">{{name}}</option></select></div>
    <div class="ph-storage-note"><PhotosIcon name="drive"/><p>Your photos stay in their existing folders.</p></div>
   </nav>
   <div class="ph-content">
    <div class="ph-heading"><div><h1>{{mode==='folders'?'Albums':mode==='favorites'?'Favourites':'Photos'}}</h1><p>{{folder==='/'?source:folder}} <span v-if="mode!=='folders'">· By file date</span></p></div><button class="ph-primary" :disabled="!source||uploading||busy" @click="$refs.fileInput.click()"><PhotosIcon name="upload"/>Upload</button><input ref="fileInput" type="file" multiple accept="image/*,video/*,.heic,.heif" hidden @change="upload($event.target.files)"/></div>
    <div v-if="mode!=='folders'" class="ph-filters"><button v-for="filter in filters" :key="filter.id" :class="{'ph-selected':kind===filter.id}" @click="kind=filter.id;refresh()">{{filter.label}}</button><button v-if="folder!=='/'" @click="folder='/';refresh()">All folders</button><span v-if="items.length">{{items.length}} loaded</span></div>
    <p v-if="error" class="ph-error" role="alert">{{error}} <button @click="refresh">Refresh library</button></p>
    <div v-if="uploadFailure&&!uploading" class="ph-error ph-upload-recovery" role="alert"><strong>Upload paused · {{uploadFailure.files.length}} remaining</strong><p>{{uploadFailure.message}}</p><p>Destination: {{uploadFailure.source}}{{uploadFailure.folder}}. Keep this page open to retry. Completed files will not be uploaded again.</p><button class="ph-primary" @click="retryUploads">Retry remaining uploads</button><button @click="refresh">Refresh library</button><button v-if="uploadFailure.status===409" @click="skipFailedUpload">Skip this file and continue</button><button @click="uploadFailure=null">Dismiss</button></div>
    <p v-if="uploadNotice&&!uploading" class="ph-upload-status" role="status">{{uploadNotice}}</p>
    <div v-if="uploading" class="ph-upload-status" role="status"><PhotosIcon name="upload"/><span>{{uploadStatus}}</span><progress :value="uploadPercent" max="100"/></div>
    <div v-if="mode==='folders'" class="ph-albums"><button class="ph-album" @click="mode='photos';folder='/';refresh()"><PhotosIcon name="photo"/><strong>All photos</strong><span>{{source}}</span></button><button v-for="album in albums" :key="album.path" class="ph-album" @click="mode='photos';folder=album.path;refresh()"><PhotosIcon name="folder"/><strong>{{album.name}}</strong><span>Folder album</span></button><button v-if="folder!=='/'" class="ph-album" @click="folder=parent(folder);refresh()"><PhotosIcon name="left"/><strong>Parent folder</strong></button></div>
    <div v-else>
     <section v-for="group in groups" :key="group.date" class="ph-day"><h2>{{group.label}}</h2><div class="ph-grid"><div v-for="item in group.items" :key="item.id" class="ph-tile"><button class="ph-image" :aria-label="'Open '+item.name" @click="open(item)"><img v-if="!failedImages.has(item.id)" :src="api.thumbnail(item)" :alt="item.name" loading="lazy" decoding="async" @error="failedImages.add(item.id)"/><div v-else class="ph-placeholder"><PhotosIcon :name="item.kind==='video'?'video':'photo'"/><span>{{item.name}}</span></div><span v-if="item.kind==='video'" class="ph-video-badge"><PhotosIcon name="video"/>Video</span></button><button class="ph-tile-star" :class="{'ph-favourite':item.favorite}" :aria-label="(item.favorite?'Remove from':'Add to')+' favourites: '+item.name" @click="favorite(item)"><PhotosIcon name="star"/></button></div></div></section>
     <div v-if="!busy&&!items.length&&!error" class="ph-empty"><div><PhotosIcon :name="mode==='favorites'?'star':'photo'"/></div><h2>{{mode==='favorites'?'Keep your favourites together':'Your photos, beautifully organised'}}</h2><p>{{mode==='favorites'?'Tap a star on any photo or video to save it here.':'Choose a library or upload photos and videos to this folder.'}}</p><button v-if="mode!=='favorites'" class="ph-primary" :disabled="!source" @click="$refs.fileInput.click()">Upload photos</button></div>
     <div class="ph-loading" role="status" v-if="busy">Loading your library…</div><button v-if="next&&!busy" class="ph-more" @click="loadMore">Load more</button>
    </div>
   </div>
  </div>
  <div v-if="selected" class="ph-viewer" role="dialog" aria-modal="true" :aria-label="selected.name" @keydown.esc="close" @keydown.left.prevent="step(-1)" @keydown.right.prevent="step(1)" tabindex="-1" ref="viewer">
   <div class="ph-viewer-bar"><button aria-label="Close photo" @click="close"><PhotosIcon name="close"/></button><strong>{{selected.name}}</strong><button :aria-label="selected.favorite?'Remove from favourites':'Add to favourites'" :class="{'ph-favourite':selected.favorite}" @click="favorite(selected)"><PhotosIcon name="star"/></button><a v-if="selected.permissions?.download!==false" :href="api.download(selected)" :download="selected.name" aria-label="Download original"><PhotosIcon name="download"/></a><button aria-label="Photo information" @click="details=!details"><PhotosIcon name="info"/></button></div>
   <button class="ph-previous" aria-label="Previous photo" :disabled="selectedIndex===0" @click="step(-1)"><PhotosIcon name="left"/></button>
   <div class="ph-media"><p v-if="!mediaURL&&!viewerError">Loading original…</p><p v-if="viewerError" role="alert">{{viewerError}} <a :href="api.browse(selected)" target="_blank" rel="noopener">Open in FileBrowser</a></p><video v-if="mediaURL&&selected.kind==='video'" :key="mediaURL" :src="mediaURL" controls playsinline preload="metadata" @error="viewerError='This video format may need another player.'"/><img v-else-if="mediaURL" :key="mediaURL" :src="mediaURL" :alt="selected.name" @error="viewerError='Your browser cannot display this image format.'"/></div>
   <button class="ph-next" aria-label="Next photo" :disabled="selectedIndex>=items.length-1" @click="step(1)"><PhotosIcon name="right"/></button>
   <aside v-if="details" class="ph-details"><h2>Details</h2><dl><dt>File</dt><dd>{{selected.name}}</dd><dt>Modified</dt><dd>{{dateTime(selected.modified)}}</dd><dt>Size</dt><dd>{{size(selected.size)}}</dd><dt>Folder</dt><dd>{{selected.source}}{{parent(selected.path)}}</dd></dl><a :href="api.browse(selected)" target="_blank" rel="noopener">Open in FileBrowser</a></aside>
  </div>
 </section>
</template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue';
import PhotosIcon from './PhotosIcon.vue';
const props=defineProps({api:{type:Object,required:true},standalone:{type:Boolean,default:false}});
const emit=defineEmits(['unauthorized']);
const source=ref(''),sources=ref([]),user=ref(null),folder=ref('/'),mode=ref('photos'),kind=ref(''),query=ref(''),items=ref([]),albums=ref([]),next=ref(''),busy=ref(false),error=ref(''),failedImages=ref(new Set()),accountOpen=ref(false),uploading=ref(false),uploadStatus=ref(''),uploadPercent=ref(0),fileInput=ref(null);
const uploadFailure=ref(null);
const uploadNotice=ref('');
const selected=ref(null),mediaURL=ref(''),viewerError=ref(''),details=ref(false),viewer=ref(null);let generation=0,selection=0,destroyed=false,opener=null;
const tabs=[{id:'photos',icon:'photo',label:'Photos'},{id:'favorites',icon:'star',label:'Favourites'},{id:'folders',icon:'folder',label:'Albums'}];
const filters=[{id:'',label:'All'},{id:'image',label:'Photos'},{id:'video',label:'Videos'}];
const parent=path=>path.slice(0,path.lastIndexOf('/'))||'/';
const selectedIndex=computed(()=>items.value.findIndex(x=>x.id===selected.value?.id));
const groups=computed(()=>{const map=new Map();for(const item of items.value){const d=new Date(item.modified),valid=!Number.isNaN(d.getTime()),key=valid?`${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`:'unknown';if(!map.has(key))map.set(key,{date:key,label:valid?new Intl.DateTimeFormat(undefined,{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(d):'Date unavailable',items:[]});map.get(key).items.push(item);}return [...map.values()];});
const dateTime=value=>value?new Date(value).toLocaleString():'Unavailable';
const size=value=>value>=1024*1024?(value/1024/1024).toFixed(1)+' MB':Math.round(value/1024)+' KB';
async function refresh(){const token=++generation;items.value=[];next.value='';error.value='';failedImages.value=new Set();if(!source.value)return;busy.value=true;
 try{if(mode.value==='folders'){const data=await props.api.folders(source.value,folder.value);if(token!==generation)return;albums.value=(data.folders||[]).map(x=>typeof x==='string'?{name:x,path:(folder.value.replace(/\/$/,'')+'/'+x)}:{...x,path:folder.value.replace(/\/$/,'')+'/'+x.name});}else{const result=await props.api.page({source:source.value,path:folder.value,q:query.value,kind:kind.value,favorites:mode.value==='favorites'});if(token!==generation)return;items.value=result.items;next.value=result.nextCursor;}}
 catch(e){if(token===generation)error.value=e.message;if(e.status===401)emit('unauthorized');}finally{if(token===generation)busy.value=false;}}
async function loadMore(){if(busy.value)return;const token=generation;busy.value=true;try{const result=await props.api.page({source:source.value,path:folder.value,q:query.value,kind:kind.value,favorites:mode.value==='favorites',cursor:next.value});if(token!==generation)return;const map=new Map([...items.value,...result.items].map(x=>[x.id,x]));items.value=[...map.values()].sort((a,b)=>(Date.parse(b.modified)||0)-(Date.parse(a.modified)||0)||a.path.localeCompare(b.path));next.value=result.nextCursor;}catch(e){error.value=e.message;}finally{if(token===generation)busy.value=false;}}
async function open(item){const token=++selection;if(!selected.value)opener=document.activeElement;selected.value=item;mediaURL.value='';viewerError.value='';await nextTick();viewer.value?.focus();document.addEventListener('keydown',trap);try{const url=await props.api.media(item);if(token===selection&&!destroyed)mediaURL.value=url;}catch(e){if(token===selection)viewerError.value=e.message;}}
function close(){selection++;selected.value=null;mediaURL.value='';document.removeEventListener('keydown',trap);opener?.focus();}
function trap(event){if(event.key!=='Tab'||!viewer.value)return;const controls=[...viewer.value.querySelectorAll('button:not([disabled]),a[href],video')];if(!controls.length)return;const first=controls[0],last=controls.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===viewer.value)){event.preventDefault();last.focus();}else if(!event.shiftKey&&(document.activeElement===last||document.activeElement===viewer.value)){event.preventDefault();first.focus();}}
function step(amount){const item=items.value[selectedIndex.value+amount];if(item)void open(item);}
async function favorite(item){try{await props.api.favorite(item,!item.favorite);if(mode.value==='favorites'&&!item.favorite)items.value=items.value.filter(x=>x.id!==item.id);}catch(e){error.value=e.message;}}
async function upload(files,destination=null){
 if(!files?.length||uploading.value)return;
 if(uploadFailure.value&&!destination){error.value='Retry or dismiss the paused upload before choosing more files.';return;}
 const media=[...files].filter(x=>/^image\/|^video\//.test(x.type)||/\.(heic|heif)$/i.test(x.name));
 if(!media.length){error.value='Choose photo or video files.';return;}
 const target=destination||{source:source.value,folder:folder.value};
 uploading.value=true;error.value='';uploadNotice.value='';uploadStatus.value='Preparing upload…';uploadPercent.value=0;
 try{
  const saved=await props.api.upload(target.source,target.folder,media,p=>{uploadStatus.value=`${p.name} · ${p.completed}/${p.total} saved${p.phase==='saving'?' · Saving…':p.phase==='renaming'?' · Choosing an available name…':''}`;uploadPercent.value=p.percent;});
  const renamed=(saved||[]).filter(file=>file.renamed).length;
  uploadNotice.value=`${media.length} uploaded${renamed?` · ${renamed} duplicate${renamed===1?'':'s'} saved with a numbered name`:''}.`;
  uploadFailure.value=null;await refresh();
 }catch(e){
  uploadFailure.value={...target,files:e.remainingFiles||media,message:e.message,status:e.status};
  await refresh();
 }finally{uploading.value=false;if(fileInput.value)fileInput.value.value='';}
}
function retryUploads(){const failed=uploadFailure.value;if(failed)void upload(failed.files,failed);}
function skipFailedUpload(){const failed=uploadFailure.value;if(!failed)return;const remaining=failed.files.slice(1);if(!remaining.length){uploadFailure.value=null;return;}void upload(remaining,failed);}
function drop(event){if(source.value)void upload(event.dataTransfer.files);}
onMounted(async()=>{try{user.value=await props.api.profile();sources.value=await props.api.sources();source.value=sources.value[0]||'';await refresh();}catch(e){error.value=e.message;if(e.status===401)emit('unauthorized');}});
onBeforeUnmount(()=>{destroyed=true;generation++;selection++;document.removeEventListener('keydown',trap);});
</script>
